app = FastAPI(title="Deep Search Agent Frontend", description="Autonomous research agent web interface", version="1.0.0")

app.add_middleware(CORSMiddleware, allow_origins=["*"], allow_credentials=True, allow_methods=["*"], allow_headers=["*"])

class ResearchRequest(BaseModel):
    topic: str
    max_time_minutes: int = 90
    report_length_pages: int = 25
    depth: str = "deep"

class ResearchStatus(BaseModel):
    call_id: str
    status: str
    progress: int
    current_phase: str
    sources_found: int
    elapsed_time: float
    estimated_remaining: float

class ResearchResult(BaseModel):
    call_id: str
    topic: str
    report: str
    stats: Dict[str, Any]
    timestamp: str

class ResearchManager:
    def __init__(self):
        self.active_researches: Dict[str, Dict] = {}
        self.completed_researches: Dict[str, ResearchResult] = {}
        self.websocket_connections: Dict[str, List[WebSocket]] = {}
        self.research_logs: Dict[str, List[str]] = {}

    def start_research(self, call_id: str, topic: str):
        self.active_researches[call_id] = {
            "topic": topic,
            "status": "running",
            "progress": 0,
            "current_phase": "initialization",
            "sources_found": 0,
            "start_time": datetime.now(),
            "phases": [],
            "iterations": 0
        }
        self.research_logs[call_id] = []
        self.add_log(call_id, f"Research initialized for: {topic}")

    def update_progress(self, call_id: str, progress: int, phase: str, sources: int = 0):
        if call_id in self.active_researches:
            self.active_researches[call_id]["progress"] = progress
            self.active_researches[call_id]["current_phase"] = phase
            self.active_researches[call_id]["sources_found"] = sources
            if phase not in self.active_researches[call_id]["phases"]:
                self.active_researches[call_id]["phases"].append(phase)

    def complete_research(self, call_id: str, result: ResearchResult):
        if call_id in self.active_researches:
            del self.active_researches[call_id]
        self.completed_researches[call_id] = result
        self.add_log(call_id, f"Research completed successfully")

    def get_status(self, call_id: str) -> Optional[Dict]:
        if call_id in self.active_researches:
            status = self.active_researches[call_id].copy()
            elapsed = (datetime.now() - status["start_time"]).total_seconds()
            status["elapsed_time"] = elapsed
            status["estimated_remaining"] = max(0, 5400 - elapsed)
            status["start_time"] = status["start_time"].isoformat()
            return status
        elif call_id in self.completed_researches:
            return {"status": "completed", "call_id": call_id}
        return None

    def add_log(self, call_id: str, message: str):
        if call_id not in self.research_logs:
            self.research_logs[call_id] = []
        timestamp = datetime.now().strftime("%H:%M:%S")
        log_entry = f"[{timestamp}] {message}"
        self.research_logs[call_id].append(log_entry)
        if len(self.research_logs[call_id]) > 1000:
            self.research_logs[call_id] = self.research_logs[call_id][-1000:]

    def get_logs(self, call_id: str) -> List[str]:
        return self.research_logs.get(call_id, [])

    async def broadcast_update(self, call_id: str, message: Dict):
        if call_id in self.websocket_connections:
            dead_connections = []
            for ws in self.websocket_connections[call_id]:
                try:
                    await ws.send_json(message)
                except:
                    dead_connections.append(ws)
            for ws in dead_connections:
                self.websocket_connections[call_id].remove(ws)

research_manager = ResearchManager()

try:
    modal_app = modal.App.lookup("deep-search-agent", create_if_missing=False)
except:
    modal_app = None

async def call_backend_research(topic: str) -> str:
    if modal_app is None:
        return ""
    try:
        api_start_research = modal_app.function_lookup("api_start_research")
        result = await api_start_research.remote.aio({"topic": topic})
        return result.get("call_id", "")
    except Exception as e:
        print(f"Modal call error: {e}")
        return ""

