            const topic = document.getElementById('topic').value.trim();
            const depth = document.getElementById('depth').value;
            const reportLength = parseInt(document.getElementById('reportLength').value);

            if (!topic) {
                showNotification('Kérlek adj meg egy kutatási témát!', 'error');
                return;
            }

            if (topic.length < 20) {
                showNotification('A kutatási téma túl rövid. Adj meg részletesebb leírást!', 'error');
                return;
            }

            const startBtn = document.getElementById('startBtn');
            const btnText = document.getElementById('btnText');
            startBtn.disabled = true;
            btnText.innerHTML = '⏳ Indítás... <span class="loading-spinner"></span>';

            try {
                const response = await fetch('/api/research/start', {
                    method: 'POST',
                    headers: {'Content-Type': 'application/json'},
                    body: JSON.stringify({
                        topic: topic,
                        depth: depth,
                        report_length_pages: reportLength
                    })
                });

                const data = await response.json();

                if (data.error) {
                    showNotification('Hiba: ' + data.error, 'error');
                    startBtn.disabled = false;
                    btnText.textContent = '🚀 Kutatás indítása';
                    return;
                }

                currentCallId = data.call_id;
                startTime = Date.now();

                document.getElementById('searchSection').style.display = 'none';
                document.getElementById('statusSection').classList.add('active');

                showNotification('Kutatás sikeresen elindítva!', 'success');
                addLog('✅ Kutatás elindítva: ' + data.call_id, 'success');
                addLog('📊 Téma: ' + topic);

                connectWebSocket(currentCallId);
                startStatusPolling();
                startTimeUpdate();

            } catch (error) {
                showNotification('Hiba történt: ' + error.message, 'error');
                startBtn.disabled = false;
                btnText.textContent = '🚀 Kutatás indítása';
            }
        }

        function connectWebSocket(callId) {
            const protocol = window.location.protocol === 'https:' ? 'wss:' : 'ws:';
            const wsUrl = `${protocol}//${window.location.host}/ws/${callId}`;

            ws = new WebSocket(wsUrl);

            ws.onopen = () => {
                addLog('🔗 WebSocket kapcsolat létrejött', 'success');
            };

            ws.onmessage = (event) => {
                const data = JSON.parse(event.data);
                updateStatus(data);
            };

            ws.onerror = (error) => {
                addLog('⚠️ WebSocket hiba', 'warning');
            };

            ws.onclose = () => {
                addLog('🔌 WebSocket kapcsolat lezárva', 'warning');
            };
        }

        function startStatusPolling() {
            statusInterval = setInterval(async () => {
                if (!currentCallId) return;

                try {
                    const response = await fetch(`/api/research/status/${currentCallId}`);
                    const data = await response.json();

                    updateStatus(data);

                    if (data.status === 'completed') {
                        clearInterval(statusInterval);
                        clearInterval(timeUpdateInterval);
                        await fetchResult();
                    }

                } catch (error) {
                    console.error('Status polling error:', error);
                }
            }, 5000);
        }

        function startTimeUpdate() {
            timeUpdateInterval = setInterval(() => {
                if (!startTime) return;

                const elapsed = Math.floor((Date.now() - startTime) / 1000);
                const remaining = Math.max(0, 5400 - elapsed);

                document.getElementById('elapsedTime').textContent = formatTime(elapsed);
                document.getElementById('elapsedMinutes').textContent = Math.floor(elapsed / 60) + ' perc';
                document.getElementById('remainingTime').textContent = formatTime(remaining);
                document.getElementById('remainingMinutes').textContent = Math.floor(remaining / 60) + ' perc';
            }, 1000);
        }

        function updateStatus(data) {
            if (data.progress !== undefined) {
                const progress = Math.min(100, Math.max(0, data.progress));
                document.getElementById('progressFill').style.width = `${progress}%`;
                document.getElementById('progressFill').textContent = `${progress}%`;
                document.getElementById('progressPercent').textContent = `${progress}%`;
            }

            if (data.current_phase) {
                const phaseMap = {
                    'initialization': 'Inicializálás',
                    'exploration': 'Felfedezés',
                    'deep_dive': 'Mélyreható elemzés',
                    'cross_validation': 'Kereszt-validáció',
                    'synthesis': 'Szintézis',
                    'validation': 'Validáció',
                    'report_generation': 'Jelentés készítés'
                };
                const hunPhase = phaseMap[data.current_phase] || data.current_phase;
                document.getElementById('currentPhase').textContent = hunPhase;
                document.getElementById('phaseLabel').textContent = 'Fázis: ' + hunPhase;
            }

            if (data.sources_found !== undefined) {
                document.getElementById('sourcesCount').textContent = data.sources_found;
            }

            if (data.iterations !== undefined) {
                document.getElementById('iterationCount').textContent = data.iterations;
            }
        }

        async function fetchResult() {
            try {
                const response = await fetch(`/api/research/result/${currentCallId}`);
                const data = await response.json();

                document.getElementById('statusSection').classList.remove('active');
                document.getElementById('resultSection').classList.add('active');

                if (data.stats) {
                    document.getElementById('statTotalSources').textContent = data.stats.total_sources || 0;
                    document.getElementById('statQualitySources').textContent = data.stats.high_quality_sources || 0;
                    document.getElementById('statDuration').textContent = Math.round(data.stats.research_duration_minutes || 0) + ' perc';
                    document.getElementById('statReportLength').textContent = Math.round((data.report.split(' ').length / 500)) + ' oldal';
                }

                const preview = data.report.substring(0, 8000);
                const previewHtml = convertMarkdownToHtml(preview);
                document.getElementById('reportPreview').innerHTML = previewHtml + '<p><strong>... (folytatás a teljes letöltött jelentésben)</strong></p>';

                showNotification('Kutatás sikeresen befejezve!', 'success');
                addLog('✅ Kutatás befejezve', 'success');

            } catch (error) {
                showNotification('Hiba az eredmény betöltésekor: ' + error.message, 'error');
                addLog('❌ Eredmény betöltési hiba: ' + error.message, 'error');
            }
        }

        async function downloadReport() {
            if (!currentCallId) return;

            try {
                window.location.href = `/api/research/download/${currentCallId}`;
                showNotification('Jelentés letöltése megkezdődött', 'success');
            } catch (error) {
                showNotification('Hiba a letöltés során: ' + error.message, 'error');
            }
        }

        function newResearch() {
            currentCallId = null;
            startTime = null;

            if (statusInterval) clearInterval(statusInterval);
            if (timeUpdateInterval) clearInterval(timeUpdateInterval);
            if (ws) ws.close();

            document.getElementById('resultSection').classList.remove('active');
            document.getElementById('searchSection').style.display = 'block';
            document.getElementById('topic').value = '';
            document.getElementById('logs').innerHTML = '<div class="log-entry success">🚀 Rendszer inicializálása...</div>';
            document.getElementById('startBtn').disabled = false;
            document.getElementById('btnText').textContent = '🚀 Kutatás indítása';

            document.getElementById('progressFill').style.width = '0%';
            document.getElementById('progressFill').textContent = '0%';
            document.getElementById('sourcesCount').textContent = '0';
            document.getElementById('iterationCount').textContent = '0';
            document.getElementById('apiCalls').textContent = '0';
        }

        function addLog(message, type = 'info') {
            const logs = document.getElementById('logs');
            const entry = document.createElement('div');
            entry.className = 'log-entry ' + type;
            const timestamp = new Date().toLocaleTimeString('hu-HU');
            entry.textContent = `[${timestamp}] ${message}`;
            logs.appendChild(entry);
            logs.scrollTop = logs.scrollHeight;

            const logCount = logs.children.length;
            document.getElementById('logCount').textContent = logCount + ' bejegyzés';

            if (logCount > 500) {
                logs.removeChild(logs.firstChild);
            }
        }

        function formatTime(seconds) {
            const mins = Math.floor(seconds / 60);
            const secs = seconds % 60;
            return `${mins}:${secs.toString().padStart(2, '0')}`;
        }

        function convertMarkdownToHtml(markdown) {
            let html = markdown;

            html = html.replace(/### (.*?)$/gm, '<h3>$1</h3>');
            html = html.replace(/## (.*?)$/gm, '<h2>$1</h2>');
            html = html.replace(/# (.*?)$/gm, '<h1>$1</h1>');

            html = html.replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>');
            html = html.replace(/\*(.*?)\*/g, '<em>$1</em>');

            html = html.replace(/\n\n/g, '</p><p>');
            html = '<p>' + html + '</p>';

            return html;
        }

        document.getElementById('topic').addEventListener('keydown', function(e) {
            if (e.key === 'Enter' && (e.ctrlKey || e.metaKey)) {
                startResearch();
            }
        });
    </script>
</body>
</html>"""
    return HTMLResponse(content=html_content)

