@app.websocket("/ws/{call_id}")
async def websocket_endpoint(websocket: WebSocket, call_id: str):
    await websocket.accept()
    if call_id not in research_manager.websocket_connections:
        research_manager.websocket_connections[call_id] = []
    research_manager.websocket_connections[call_id].append(websocket)
    try:
        status = research_manager.get_status(call_id)
        if status:
            await websocket.send_json(status)
        while True:
            data = await websocket.receive_text()
            await websocket.send_json({"type": "pong", "timestamp": datetime.now().isoformat()})
    except WebSocketDisconnect:
        if call_id in research_manager.websocket_connections:
            research_manager.websocket_connections[call_id].remove(websocket)

