<body>
    <div class="notification" id="notification">
        <p id="notificationText"></p>
    </div>

    <div class="container">
        <div class="header">
            <h1>🤖 Deep Search Agent</h1>
            <p>Autonóm kutatási rendszer mély intelligenciával • 90 perces autonóm működés</p>
        </div>

        <div class="content">
            <div class="search-section" id="searchSection">
                <h2>📚 Új kutatás indítása</h2>

                <div class="form-group">
                    <label for="topic">Kutatási téma *</label>
                    <textarea 
                        id="topic" 
                        placeholder="Pl: A kvantumszámítás hatása a kriptográfiára és kiberbiztonságra a következő évtizedben. Milyen kvantum-rezisztens algoritmusok léteznek, és hogyan készülnek fel a szervezetek a kvantum-fenyegetésre?"
                        rows="4"
